// 一口气完成：统计 sessions → 建目录 → 镜像复制四个数据源 → 过滤敏感文件 → 检查
const r = await tools.pwsh({
  command: `
$ErrorActionPreference = 'Stop'
$dst = 'D:/GitHub/My-second-brain/60-DSH数据'
New-Item -ItemType Directory -Force -Path "$dst/灵枢mdcg","$dst/OpenViking","$dst/grill-first偏好","$dst/会话sessions","$dst/会话storages" | Out-Null

# 镜像复制（先清空目标再拷，保证镜像语义）
foreach ($pair in @(
  @('C:/Users/jjq21/.dsh/.dsh-memory', "$dst/灵枢mdcg"),
  @('C:/Users/jjq21/.openviking', "$dst/OpenViking"),
  @('C:/Users/jjq21/.dsh/grill-first', "$dst/grill-first偏好"),
  @('C:/Users/jjq21/.dsh/sessions', "$dst/会话sessions"),
  @('C:/Users/jjq21/.dsh/storages', "$dst/会话storages")
)) {
  if (Test-Path $pair[1]) { Remove-Item $pair[1] -Recurse -Force }
  Copy-Item $pair[0] $pair[1] -Recurse -Force
}

# 敏感文件过滤：按文件名/扩展名
$pattern = 'credential|secret|token|\.env$|\.pem$|\.key$'
$hits = Get-ChildItem $dst -Recurse -File | Where-Object { $_.Name -match $pattern }
if ($hits) { $hits | ForEach-Object { "SENSITIVE: $($_.FullName)"; Remove-Item $_.FullName -Force } } else { "无敏感文件名命中" }

# 体积与文件数
foreach ($d in Get-ChildItem $dst -Directory) {
  $m = Get-ChildItem $d.FullName -Recurse -File | Measure-Object Length -Sum
  "{0,-18} {1,8:N2} MB  {2,5} files" -f $d.Name, ($m.Sum/1MB), $m.Count
}
`,
  description: "镜像复制记忆数据进仓库并过滤敏感文件"
});
console.log(r.stdout);
if (r.stderr && r.stderr.text) console.error("STDERR:", r.stderr.text);
console.log("exit:", r.exitCode);
